import type {Seed} from './content';
import type {NumberCheck} from './engine';
export type CareerFamily=Seed&{topic:string;probeAnswers:[string,string];numbers?:NumberCheck[]};
const f=(topic:string,title:string,prompt:string,facts:string[],task:string,benchmark:string,q1:string,a1:string,q2:string,a2:string,numbers:NumberCheck[]=[]):CareerFamily=>({topic,title,prompt,facts,task,benchmark,followups:[q1,q2],probeAnswers:[a1,a2],numbers});
// Original scenarios. Probe answers address the changed constraint, rather than recycling the core answer.
export const careerFamilies:Record<string,CareerFamily[]>={
banking:[
f('Valuation','The terminal-value trap','Audit a fictional acquisition model before it reaches the client.',['Next-year terminal free cash flow is $12m. WACC is 10%; perpetual growth is 3%.','The analyst divides $12m by WACC and ignores growth.'], 'Calculate terminal value at the terminal date and explain the model error.','Terminal value is 12/(.10−.03)=$171.43m, not $120m. It must still be discounted to the valuation date. Check whether cash flow is already the next-year amount and whether growth, reinvestment and margins are sustainable.','What if growth rises to 4%?','Value becomes $200m at the terminal date. Explain the sensitivity and test whether higher growth requires reinvestment that reduces free cash flow.','What if growth equals WACC?','The perpetuity formula is undefined; this is not evidence of unlimited economic value. Use defensible assumptions or a finite explicit forecast and justify terminal economics.',[{label:'Terminal value at terminal date',answer:171.428571,tolerance:.01,unit:'$m'}]),
f('M&A','Synergies before the invoice','Advise a fictional buyer on a synergy claim.',['Annual pre-tax cost savings are $20m starting next year; tax rate is 25%.','Integration costs $30m immediately. Assume savings last five years and discount at 10%.'], 'Estimate synergy NPV and identify risks that could make the acquisition overvalued.','After-tax savings are $15m annually. Five-year annuity factor at 10% is about 3.7908, giving $56.86m present value and $26.86m net of integration. Do not add this entire value to the seller price without considering execution risk and who captures the surplus.','Savings start a year later. What changes?','Discount the five-payment annuity one additional year: $56.86m/1.1−$30m≈$21.69m. Verify that five payments still occur rather than shortening the benefit period.','Half the savings require unapproved closures. What do you do?','Separate committed and contingent savings, probability-weight or scenario-test the contingent component, and examine implementation approvals, costs and customer disruption.',[{label:'Synergy NPV',answer:26.8618,tolerance:.02,unit:'$m'}]),
f('Accounting','A deferred-revenue misunderstanding','A fictional target collects cash before delivering a service.',['A customer pays $120,000 on January 1 for twelve equal months of service.','No refunds or taxes; service is delivered evenly.'], 'Explain cash, revenue and deferred revenue at March 31.','Cash received is $120,000; three months of revenue total $30,000 and deferred revenue is $90,000. Cash collection is not the same as earned revenue. Explain the remaining delivery obligation and verify contract terms.','How would a mid-year cancellation right affect diligence?','Inspect refund provisions and collectibility, model cash refunds and assess the remaining obligation. Do not assume the original schedule remains valid after a contract change.','Can the buyer treat all deferred revenue as free cash?','No. The buyer inherits delivery obligations and possibly refunds; examine fulfillment costs and the transaction’s working-capital and debt-like definitions.',[{label:'Deferred revenue at March 31',answer:90000,tolerance:1,unit:'$'}]),
f('Capital structure','Refinance or wait?','Compare fictional refinancing alternatives.',['Outstanding debt is $100m at 8% interest; replacement debt would cost 6%.','Refinancing fees are $3m paid now; ignore taxes and discounting for the initial comparison.'], 'Calculate annual interest savings and simple fee payback; identify what the shortcut misses.','Annual interest falls by $2m; fee payback is 1.5 years. Compare remaining maturities, covenants, amortization, call premiums, floating-rate exposure and liquidity before recommending refinancing.','The loan will be repaid in one year. Is the refinance attractive?','Only $2m of simple savings is realized versus $3m fees, so it loses $1m before other factors. Check whether strategic covenant relief has separate value.','What if the new debt is floating-rate?','Model a rate path and sensitivity rather than using 6% for every year. Consider caps or hedges, their costs and covenant headroom.',[{label:'Simple fee payback',answer:1.5,tolerance:.01,unit:'years'}]),
f('LBO','An exit multiple rescue','Review a fictional sponsor return.',['Entry enterprise value is $200m, funded with $120m debt and $80m equity.','Exit EBITDA is $25m; exit debt is $70m; exit multiple is 8×; no cash or interim distributions.'], 'Calculate exit equity and money multiple, then distinguish operational value from leverage.','Exit EV is $200m, exit equity $130m and equity multiple 1.625×. Debt repayment raises equity value even without EV growth. Explain cash conversion, leverage risk and the holding period before quoting IRR.','Exit multiple falls to 6×. What happens?','EV is $150m, equity $80m and the multiple is 1×. This excludes fees and time value, so nominal capital preservation is not an attractive return.','Can EBITDA growth alone support the debt repayment?','No. Bridge EBITDA to free cash flow after interest, tax, capex and working capital, then reconcile the projected $50m debt reduction.',[{label:'Base equity money multiple',answer:1.625,tolerance:.001,unit:'×'}]),
f('Equity markets','The rights issue headline','Analyze a fictional equity raise.',['There are 100m shares trading at $20.','The company issues 25m new shares at $16; ignore fees and assume no new information or value creation.'], 'Calculate theoretical ex-rights price and explain dilution versus value transfer.','Pre-issue equity is $2,000m and proceeds $400m. Theoretical ex-rights price is $2,400m/125m=$19.20. Ownership dilution differs from economic loss when existing holders receive appropriately valued rights. Explain assumptions rather than predicting market price.','What if proceeds fund a negative-NPV project?','The mechanical price calculation omits value destruction. Deduct the project’s expected negative NPV and discuss uncertainty instead of equating cash raised with value created.','Why can the actual stock price differ?','Information about project quality, financing need, fees, market conditions and demand changes price. Theoretical ex-rights pricing isolates the arithmetic under fixed assumptions.',[{label:'Theoretical ex-rights price',answer:19.2,tolerance:.01,unit:'$'}]),
f('Diligence','The customer that pays early','Investigate a fictional target’s unusually strong year-end cash.',['One customer accounts for 35% of sales.','The customer prepaid next quarter after receiving a steep discount; reported year-end receivables fell.'], 'Prepare diligence questions and a normalized working-capital approach.','Separate sustainable collection improvement from pulled-forward cash and discounting. Inspect the contract, post-close fulfillment costs, customer concentration, cutoff and subsequent receipts. Use a representative seasonal baseline rather than treating one unusually strong date as normal.','The seller says the prepayment happens annually. What evidence is needed?','Examine multiple years of contracts, timing and discounts, including whether terms changed. A recurring seasonal pattern can be normalized but does not eliminate concentration risk.','How would you communicate a disputed adjustment?','Document facts, methodology, range and alternative treatments. Escalate the commercial judgment and avoid presenting an unresolved adjustment as agreed.'),
f('Professional judgment','A pitch with an unsupported claim','A fictional deal team wants to cite an unverified market-size estimate.',['The only source is a competitor’s marketing slide.','The client meeting is tomorrow and the estimate materially affects the thesis.'], 'Draft a response and a defensible replacement analysis.','Flag the source limitation, triangulate with credible primary evidence and separate a range from a precise fact. State assumptions and update the pitch transparently. Preserve the deadline through scoped analysis, not invented confidence.','A senior banker insists on the point estimate. What next?','Explain the material risk, propose qualified wording and a source note, and use the appropriate review escalation if it remains unsupported. Be specific without making the dispute personal.','You discover an error after the meeting. What do you do?','Quantify impact, inform the responsible team promptly and arrange a clear correction to recipients. Keep an audit trail and improve the verification step.')
],
consulting:[
f('Operations','The bottleneck nobody owns','A fictional repair center wants to double throughput.',['Inspection handles 40 units/hour; repair handles 25; packaging handles 50.','Demand is 35 units/hour and each completed unit contributes $30 before fixed costs.'], 'Identify the bottleneck and evaluate increasing repair capacity to 35/hour.','Current throughput is at most 25/hour. Repair expansion can raise it to 35/hour if demand, staffing and reliability hold, adding up to $300 contribution/hour before incremental costs. Faster packaging alone does not raise system throughput.','Inspection drops to 30/hour during breaks. What changes?','Effective throughput becomes at most 30/hour in those periods. Model staffing schedules and variability rather than multiplying peak rates by all operating hours.','How would you validate the investment?','Pilot throughput, queue length, quality and labor cost over representative shifts. Require realized incremental contribution above expansion cost.',[{label:'Maximum incremental hourly contribution',answer:300,tolerance:.01,unit:'$'}]),
f('Pricing','Discounts that erase the win','A fictional retailer wants a volume promotion.',['Current volume is 10,000 units at $50 with $30 variable cost.','A 10% price cut is expected to increase volume 20%; fixed costs do not change.'], 'Compare contribution and calculate volume needed to preserve it.','Current contribution is $200,000. New unit margin is $15, yielding $180,000 at 12,000 units. Preserving contribution requires 13,333.33 units, or at least 13,334 whole units. Assess demand evidence, capacity and customer response.','Variable cost falls to $28 at the new volume. What changes?','New contribution becomes $17×12,000=$204,000. Verify whether the cost reduction applies to every unit and is sustainable, rather than a marginal supplier rebate.','How would you test willingness to pay?','Design a lawful, controlled price or offer test with comparable cohorts, contribution and retention guardrails; avoid inferring elasticity from a concurrent seasonality change.',[{label:'Contribution after promotion',answer:180000,tolerance:1,unit:'$'}]),
f('Market entry','A market too large to serve','A fictional B2B startup wants to enter a region.',['There are 2,000 target firms; 30% meet technical requirements.','Of qualified firms, 20% might buy at $10,000 annually. The sales team can onboard only 60 customers this year.'], 'Estimate the qualified opportunity and capacity-limited first-year revenue.','Qualified customers number 600 and potential buyers 120, implying $1.2m annual revenue at full capture of that assumed segment. Onboarding capacity limits first-year customers to 60 and annualized revenue to $600,000; recognized revenue depends on start dates.','Half the customers start halfway through the year. What revenue is recognized?','If 30 start at year start and 30 at midyear with straight-line service, first-year revenue is $300k+$150k=$450k. State assumptions about churn and payment terms.','Which assumption should be tested first?','Prioritize the most decision-sensitive uncertain assumption, such as purchase propensity or eligibility. Use customer evidence, not the multiplication itself, to support the forecast.',[{label:'Capacity-limited annualized revenue',answer:600000,tolerance:1,unit:'$'}]),
f('Procurement','The cheaper supplier costs more','Compare fictional component suppliers.',['Supplier A charges $12 per unit with 1% rejects. Supplier B charges $11 with 8% rejects.','You need 10,000 usable units; rejects cannot be recovered. Ignore freight initially.'], 'Compare expected procurement cost per usable unit and identify other decision criteria.','A costs 12/.99≈$12.12 per usable unit; B costs 11/.92≈$11.96. B is slightly cheaper on this simplified basis, but quality variance, downtime, inspection and delivery may erase the difference. Do not compare sticker prices alone.','B also requires $3,000 extra inspection. What happens?','For 10,000 usable units, B costs about $119,565+$3,000=$122,565 versus A about $121,212. A becomes cheaper under these assumptions.','How would a single-source risk affect the choice?','Assess supplier capacity, disruption probabilities, qualification lead time and buffer cost. A dual-source option can be justified even if expected purchase cost rises.'),
f('Growth','Retention before acquisition','A fictional subscription business allocates a growth budget.',['1,000 customers pay $100 monthly. Monthly churn is 5%.','A retention initiative costs $2,000 monthly and is expected to reduce churn to 3%; gross margin is 80%.'], 'Calculate first-month retained gross profit and explain what is needed for a longer-term decision.','The initiative retains 20 additional customers in the first month, or $1,600 gross profit, below its $2,000 monthly cost. Longer-term cohort benefits may justify it; model survival, incremental acquisition, recurring cost and causality instead of extrapolating one month.','What if the retained customers are low-margin?','Segment contribution and support costs. Use the economics of customers actually affected by the intervention, not the average margin of the whole base.','How would you measure incrementality?','Randomize eligible customers or use a credible comparison group, track retention and margin over time, and check that the intervention is not merely delaying cancellations.',[{label:'Additional first-month gross profit',answer:1600,tolerance:1,unit:'$'}]),
f('Organization','A merger with two operating models','A fictional client merges a centralized service business with a locally managed one.',['Both teams use different escalation rules and reporting definitions.','Management wants immediate cost savings without losing key customers.'], 'Recommend an integration sequence, owners and early warning metrics.','Map customer-critical processes and decision rights before consolidating. Standardize definitions, preserve continuity, pilot changes and phase savings against service evidence. Account for one-time integration work and retention risks rather than assuming headcount cuts are pure benefit.','Two leaders claim the same decision. How do you resolve it?','Define accountable ownership, consultation and escalation at the decision level, test the model on actual cases, and obtain explicit executive agreement.','How would you distinguish temporary disruption from a failed model?','Set baseline service metrics, transition milestones and review thresholds. Investigate persistent cohort deterioration and roll back specific process changes when evidence warrants.'),
f('Sustainability','The fleet replacement decision','Evaluate a fictional fleet investment.',['A new vehicle costs $40,000 more than the alternative and saves $8,000 annually in energy and maintenance.','Expected life is six years; use a 10% discount rate, no terminal value and equal timing for other cash flows.'], 'Calculate incremental NPV and discuss operational constraints.','Six annual savings have PV about $34,842; incremental NPV is about −$5,158. A simple five-year payback misses time value. Analyze charging availability, downtime, utilization and other quantified benefits before deciding.','A $10,000 upfront subsidy is confirmed. What changes?','Incremental upfront cost falls to $30,000, making NPV about +$4,842. Confirm eligibility and timing rather than assuming an uncertain subsidy is cash.','Can you include avoided emissions?','Quantify emissions with explicit boundaries and credible factors. Include financial benefits only when a defensible cash or policy mechanism exists; report nonfinancial objectives separately.'),
f('Public sector','Shorter waits without moving the queue','A fictional city wants to improve permit processing.',['Intake takes two days, technical review ten and final authorization three.','Complex applications consume most reviewer time; some applications are incomplete.'], 'Design a diagnostic and improvement plan that protects review quality.','Map lead time versus processing time, queue sizes, rework and case mix. Test completeness checks and differentiated routing without excluding legitimate applicants. Measure end-to-end time, quality, appeals and access rather than only one stage.','Fast tracking simple cases worsens complex-case waits. What now?','Set service objectives by complexity, reserve specialist capacity and monitor aging backlogs. Evaluate total public outcomes rather than claiming success from the median alone.','Staff want an immediate headcount increase. How do you respond?','Estimate workload, effective capacity and demand variability first. A staffing increase may be justified, but separate capacity shortages from rework, approval bottlenecks and policy constraints.')
],
quant:[
f('Probability','A biased coin after two heads','Update a fictional coin model.',['One of two coins is selected with equal probability.','Coin A has P(heads)=0.5 and coin B has P(heads)=0.8. Two independent flips of the selected coin both show heads.'], 'Calculate the probability the coin is B and the predictive probability of another head.','Likelihoods are .25 and .64, so P(B|HH)=.64/.89≈.7191. Predictive head probability is .7191×.8+.2809×.5≈.7157. Condition on the shared coin rather than treating observations as marginally independent.','What if you observe heads then tails?','Likelihoods are .25 and .16, yielding P(B|HT)=.16/.41≈.3902. Order has no effect under conditionally independent stationary flips.','What if the prior probability of B is only 10%?','For HH, posterior is .1×.64/(.1×.64+.9×.25)=.064/.289≈.2215. Strong evidence need not overwhelm a low prior.',[{label:'Posterior probability of coin B after HH',answer:71.9101,tolerance:.01,unit:'%'}]),
f('Expected value','When to stop rolling','Solve a fictional one-retry game.',['A fair six-sided die is rolled. You may keep the result or reroll once.','If you reroll, the second result must be kept. Payout equals the retained number of dollars.'], 'Give an optimal policy and its expected payout.','A reroll has expected value $3.50, so reroll 1–3 and keep 4–6. Expected payout is (3×3.5+4+5+6)/6=$4.25. State risk neutrality and no reroll fee.','A reroll costs $1. What policy is optimal?','Net reroll value is $2.50. Reroll 1–2 and keep 3–6; expected net payout is (2×2.5+3+4+5+6)/6=23/6≈$3.833.','What if the player is risk averse?','Expected dollars alone may not determine the policy. Compare expected utility for each current result with the reroll lottery, including any fee.',[{label:'Optimal expected payout without fee',answer:4.25,tolerance:.001,unit:'$'}]),
f('Statistics','A strategy selected from a crowd','A fictional researcher tests 100 unrelated strategies.',['Every strategy has zero true edge.','Each test falsely rejects the null with probability 5%; assume independent tests initially.'], 'Calculate the chance of at least one false positive and propose a research process.','Probability is 1−.95^100≈99.41%. Selecting the best backtest amplifies noise. Register hypotheses, account for multiple testing and reserve untouched forward or holdout evidence; independence is an assumption, not a default market property.','What if tests are highly correlated?','The independence formula no longer applies. Dependence changes the effective search burden; use an appropriate multiplicity method or empirical null while preserving a clean final holdout.','Can you repeatedly inspect the holdout?','Repeated selection against a holdout leaks information. Use a separate final test, sequentially valid procedure or prospective evaluation rather than relabeling reused data untouched.'),
f('Market making','Inventory changes the quote','Design a fictional quoting response.',['Fair-value estimate is 100 and the current quote is 99.9/100.1.','You hold a large long inventory and face uncertain short-term order flow.'], 'Explain how inventory, adverse selection and execution costs influence the quote.','A long inventory can motivate lowering reservation price to encourage selling and discourage buying, subject to limits and market conditions. Spread and size should reflect uncertainty, costs and adverse selection. A lower ask does not guarantee a sale or profit.','Informed sellers hit your bid repeatedly. What changes?','Update the fair-value estimate and adverse-selection model; reduce or withdraw risky bid size within policy and examine whether the signal is real. Inventory skew alone cannot repair a stale estimate.','How would you evaluate the policy?','Measure risk-adjusted P&L, markouts, inventory distribution, fills and costs on representative out-of-sample data, accounting for queue position and realistic execution.'),
f('Portfolio risk','Diversification that disappears','Compare two fictional exposures.',['Each asset has volatility 20%; equal weights sum to 100%.','Base correlation is zero. Ignore leverage and use the standard covariance model.'], 'Calculate portfolio volatility and the effect of correlation rising to one.','Variance is .5²×.2²+.5²×.2²=.02, so volatility is about 14.14%. At correlation one it is 20%. Correlation stress matters, and historical covariance is not a guarantee.','What if correlation is −1?','With equal volatilities and weights the idealized model gives zero variance. Real positions retain basis, estimation, liquidity and operational risk; perfect anticorrelation is fragile.','How would you choose a stress scenario?','Use economically coherent joint shocks, historical episodes and forward-looking vulnerabilities. Test liquidity and nonlinear exposure, not only a single covariance estimate.',[{label:'Portfolio volatility at zero correlation',answer:14.1421,tolerance:.01,unit:'%'}]),
f('Research','A feature from tomorrow','Audit a fictional forecasting dataset.',['The target is next-day return.','A feature uses a revised end-of-day record whose publication timestamp is two days later; the backtest looks strong.'], 'Identify the leakage and redesign training and evaluation.','Use point-in-time availability, not the economic date on the record. Rebuild features from versions observable at prediction time and use chronological validation with appropriate gaps for overlapping labels. Compare against a simple baseline after costs.','Can shifting the column by one row fix it?','Not reliably: publication delays, revisions and calendar irregularities vary. Join by actual availability timestamps and define the prediction cutoff.','Performance vanishes after correction. What next?','Report the invalidated result, investigate legitimate lagged signals without fishing on the test set, and retain a reproducible audit of the corrected pipeline.'),
f('Options','Delta is not the whole hedge','Discuss a fictional option position.',['You are short calls with aggregate delta −500 share equivalents.','You can trade the underlying but hedge only at discrete times; volatility and prices can jump.'], 'Describe the initial delta hedge and the risks remaining.','Buy 500 shares for an initial delta-neutral position. Gamma changes delta as price moves, and vega, jumps, financing and discrete execution remain. Define rehedging thresholds, transaction costs and risk limits; delta neutrality is local.','The underlying rises sharply. What usually happens for short vanilla calls?','Short-call gamma is negative, so the option position typically becomes more negative delta as the underlying rises. Additional shares may be needed, subject to the actual contract and portfolio.','Why not rebalance continuously?','Continuous trading is impossible and costly. Optimize hedge frequency against residual risk, liquidity and execution costs under explicit assumptions.'),
f('Algorithms','Sample fairly from a stream','Implement a fictional one-item sampler.',['The stream length is unknown.','Only constant extra memory is available; each item should have equal probability of selection at the end.'], 'Write reservoir-sampling pseudocode and prove the probability.','Keep the first item. For item i, replace the sample with probability 1/i. Item j survives with (1/j)×product from k=j+1 to n of (1−1/k)=1/n. Use a suitable unbiased random integer and test distribution over repeated runs.','How do you sample k items?','Maintain a reservoir of the first k; at item i draw a uniform integer in 1..i and replace the corresponding reservoir slot if it is ≤k. Memory is O(k).','What if items have unequal desired weights?','Uniform reservoir sampling is no longer correct. Define whether weighted sampling is with or without replacement and select a suitable weighted algorithm; validate inclusion probabilities.')
],
'software-engineering':[
f('Algorithms','Merge busy calendars','Build a fictional calendar availability tool.',['Intervals are half-open [start,end) and may overlap or arrive unsorted.','Invalid intervals must be rejected; adjacent intervals may be merged.'], 'Implement interval union and explain complexity and tests.','Validate start<end, sort by start and sweep, extending the current end when the next start is at most it. Sorting costs O(n log n); the sweep is O(n). Test empty input, containment, adjacency, duplicates and negative timestamps.','What if intervals are already sorted?','Use a linear scan with O(1) working state beyond output. Confirm the ordering contract; do not quietly rely on it for arbitrary input.','How would you support live insertions?','Use an ordered interval structure and merge affected neighbors. Discuss update complexity, fragmentation and concurrency rather than re-sorting the entire history by default.'),
f('System design','A fair API limiter','Design a fictional multi-tenant API rate limiter.',['Each tenant may send 100 requests per second with a burst of 200.','Requests can hit several service instances; a noisy tenant must not starve others.'], 'Describe token accounting, atomicity, failure behavior and tests.','A token bucket refills at 100/s up to 200. Use atomic shared updates or a documented allocation scheme across instances; independent full buckets multiply the allowance. Define clock behavior, retry hints and fail-open versus fail-closed by endpoint risk.','The shared store is unavailable. What happens?','Choose bounded local allowances, rejection or fail-open based on safety and availability needs. Document the maximum overshoot and monitor degraded mode; do not claim global precision without coordination.','How do you test boundary behavior?','Use a controlled clock, simultaneous requests, refill fractions, tenant isolation and a burst at capacity. Verify both admitted counts and latency under contention.'),
f('Reliability','A retry storm','Diagnose a fictional service outage.',['Each of three call layers retries twice after the original attempt.','A downstream dependency is overloaded; requests time out but may still run.'], 'Estimate worst-case downstream amplification and propose mitigation.','Three attempts at each of three layers can produce 27 downstream attempts per original call. Use end-to-end deadlines, a bounded retry budget, backoff with jitter and admission control. Retry only suitable operations and avoid stacking policies blindly.','What if the operation changes account state?','Retries need idempotency or a reconciliation protocol. A timeout is an unknown outcome, so repeated mutations can corrupt state even if load is controlled.','How would you prove recovery?','Track original traffic separately from attempts, queue depth, saturation and successful latency. Use a staged rollout or rollback and verify the downstream system drains rather than merely hiding errors.',[{label:'Maximum downstream attempts per original call',answer:27,tolerance:0,unit:'attempts'}]),
f('Coding','An undo stack with branches','Implement a fictional document editor history.',['Commands transform a document and can provide an inverse operation.','Undo followed by a new edit discards the redo branch; invalid commands must not enter history.'], 'Write pseudocode and define command failure and snapshot behavior.','Keep undo and redo stacks; successful new edits push to undo and clear redo. Undo applies an inverse and moves the command to redo only after success. Define atomicity and memory limits, and test branching, empty stacks and failed commands.','An inverse depends on deleted content. What must be stored?','Capture enough prior state in the command or a snapshot before applying it. An operation name alone cannot reconstruct arbitrary lost content.','What changes for collaborative editing?','A local stack does not safely invert others’ concurrent changes. Define operation identity and causality and consider transformation or CRDT semantics with user-visible conflict rules.'),
f('Architecture','Search without stale deletions','Design a fictional search index fed from a database.',['Updates are delivered at least once and can arrive out of order.','Deleting an item must not allow an older update to recreate it in search.'], 'Specify versioning, tombstones, replay and correctness checks.','Use monotonic entity versions and conditional index updates; retain a deletion tombstone long enough to reject stale events. Reconcile against authoritative state and define eventual-consistency bounds. Test duplicate delivery, delete-before-update and full rebuild.','How long should tombstones remain?','Tie retention to maximum replay delay and recovery guarantees. If stale events can return indefinitely, finite retention alone cannot guarantee safety; use authoritative version checks or rebuild barriers.','A rebuild runs while writes continue. How do you cut over?','Take a consistent snapshot with a change-log watermark, replay subsequent changes, validate parity and atomically switch the read alias with a rollback plan.'),
f('Testing','A parser that accepts too much','Implement a fictional configuration parser for integer ranges.',['Valid input is two base-10 integers separated by a colon, such as 3:8.','Whitespace around tokens is allowed; lower must not exceed upper. Expressions and trailing text are invalid.'], 'Write parsing logic, validation and tests without executing input.','Use a strict full-string grammar, parse both integers with range checks and validate ordering. Reject empty tokens, overflow, extra delimiters and expressions. Never evaluate the input as code; distinguish syntax errors from out-of-range values.','Do you accept 1e3 or hexadecimal?','Not under this grammar. Reject them explicitly or change and document the contract with tests; language parsing defaults should not silently define the format.','How would property-based testing help?','Generate valid pairs and assert round trips, then mutate delimiters, ordering and boundaries. Check that accepted strings always satisfy the specified grammar and numeric limits.'),
f('Distributed systems','Choose a leader after a pause','Reason about a fictional scheduled-job system.',['Only one worker should execute each scheduled job.','A worker can pause long enough for its lease to expire, then resume while a new worker is active.'], 'Explain why a lease alone is insufficient and propose a safe execution boundary.','Use fencing tokens that increase with ownership epochs, enforced by the resource accepting writes. A resumed worker with an old token must be rejected. Combine idempotent job IDs and durable outcomes; a lock that only workers inspect cannot fence a paused process.','The external resource cannot check fencing tokens. What then?','Move effects behind a single enforcing service, use resource-supported idempotency, or accept and compensate for a documented duplicate risk. Do not promise exactly-once effects from leases alone.','How do you test the race?','Pause a worker after acquiring ownership, expire its lease, run the replacement and resume the old worker. Assert stale writes fail at the actual effect boundary.'),
f('Performance','A memory leak versus a cache','Investigate a fictional service whose memory rises daily.',['Traffic is stable; restarting restores memory temporarily.','The service caches results by a key containing user-supplied filters.'], 'Plan measurements and a safe fix.','Compare heap profiles, retained objects and key cardinality across equivalent load windows. A cache without limits may retain legitimate objects indefinitely and behave like a leak. Add bounded eviction, TTL and key validation, then measure hit rate, latency and memory.','Memory remains high after objects are freed. Is the fix wrong?','Allocator behavior and garbage-collection timing can retain process memory. Inspect live heap and allocation trends alongside resident memory before concluding objects still leak.','How would you avoid a cold-cache outage?','Roll out gradually, bound backend concurrency and use request coalescing or warming for known hot keys. Monitor misses and dependency saturation during restart.')
],
'product-management':[
f('Strategy','Build, partner or decline','Choose an approach for a fictional identity-verification feature.',['Enterprise customers request it; the team lacks compliance operations.','A partner can launch in six weeks; internal development is estimated at six months.'], 'Compare alternatives and define a decision with assumptions.','Compare strategic differentiation, time to value, total cost, reliability, data handling and ongoing operations. A partner accelerates delivery but introduces dependency and switching costs. Validate demand and minimum scope before committing to either path.','The partner changes pricing after launch. What protects you?','Negotiate change terms, exportability and exit plans; design an abstraction only where justified. Model price sensitivity and alternatives rather than assuming perpetual partner economics.','Engineering wants to build for learning. How do you respond?','Value learning explicitly against customer urgency and opportunity cost. A limited internal prototype may answer uncertainty without committing to full production ownership.'),
f('Accessibility','Voice-only onboarding','Review a fictional onboarding proposal.',['The team wants mandatory voice input to reduce typing.','Users may be in noisy spaces, use assistive technology or prefer not to speak.'], 'Define an inclusive launch scope and success measures.','Offer equivalent nonvoice paths, confirm errors and test with varied users and assistive technologies. Measure completed tasks and failure recovery by modality, not just average speed. Avoid collecting unnecessary voice data and define retention.','Voice is faster for most test participants. Is that enough?','No. Inspect recruitment bias and outcomes for excluded users. Averages cannot justify blocking access when a viable alternative exists.','How would you prioritize accessibility work?','Map barriers by task criticality and severity, include affected users, and set acceptance criteria for core flows. Treat accessibility as a requirement, not an optional engagement experiment.'),
f('Experimentation','A marketplace interference problem','Design a fictional experiment on seller ranking.',['Buyers can see sellers assigned to both treatment and control.','Seller capacity is limited, so demand shifted to one seller can affect another.'], 'Choose an experiment unit and explain interference risks.','Individual-user randomization may contaminate supply outcomes. Consider geographic or time clusters, marketplace-level measures and spillover analysis. Match design to network structure and account for fewer independent units and seasonality.','Why not simply randomize sellers?','Buyers still cross groups and sellers compete for shared demand. Seller randomization may answer a narrower question, but it does not automatically remove interference.','A switchback test alternates hourly. What is the risk?','Carryover, delayed orders and daily cycles can bias estimates. Choose washout and block lengths based on behavior, balance schedules and use an analysis matching assignment.'),
f('Monetization','An annual plan cash illusion','Evaluate a fictional subscription change.',['Monthly plan costs $20; annual plan costs $180 paid upfront.','The finance team celebrates cash growth while product sees fewer monthly renewals.'], 'Define the economics and measurement needed before expanding the offer.','Separate cash collection, revenue recognition, customer survival and contribution. Annual billing discounts a full twelve months by $60 but may improve retention or cash timing. Compare cohorts over a common horizon and account for refunds and support costs.','Can you compare monthly churn directly?','No. Contractual renewal opportunities differ. Compare aligned survival, usage, refund and eventual renewal measures rather than calling annual customers retained because they cannot yet renew.','What if only existing loyal customers switch?','The offer may mostly discount revenue that would have arrived anyway. Estimate incremental retention and acquisition using an appropriate holdout or controlled rollout.'),
f('Product execution','Launch with an unresolved dependency','A fictional product launch depends on a partner integration.',['Marketing has announced a date.','The partner’s test environment passes, but production rate limits are undocumented.'], 'Create a launch decision and contingency plan.','Confirm production limits, representative load, error handling and support ownership. Use staged eligibility, a feature flag and a rollback plan; separate the launch communication from universal availability. Do not treat a sandbox pass as production readiness.','The partner cannot answer before the date. What now?','Choose a bounded pilot, alternative workflow or delay based on failure severity. Communicate the limitation honestly with a new evidence-based checkpoint.','What metrics would stop rollout?','Set thresholds for failed tasks, latency, partner saturation and support incidents with named owners. Use customer outcomes rather than launch-date completion as success.'),
f('Discovery','Requests from the loudest customer','A fictional enterprise buyer demands a custom dashboard.',['The buyer represents 8% of revenue.','The requested fields are useful to one workflow; engineering estimates six weeks.'], 'Run discovery and recommend a reusable or bounded solution.','Understand the job to be done, commitment and alternatives, then test demand across relevant accounts. Compare retention value with maintenance and opportunity cost. A configurable export or scoped service may solve the need better than a permanent bespoke feature.','The buyer threatens to leave. Does that decide it?','Quantify credible churn risk and contribution, ask what outcome would retain them, and evaluate alternatives. A threat is evidence to investigate, not an automatic roadmap veto.','How do you avoid confirmation bias in research?','Include nonrequesting and lost customers, ask about recent behavior before pitching the solution, and document contradictory evidence.'),
f('Trust and safety','A reporting tool that gets abused','Design a fictional content-reporting workflow.',['Users can report harmful posts.','Coordinated groups sometimes mass-report legitimate posts to silence others.'], 'Propose triage, appeals and success metrics.','Separate report volume from evidence of policy violation. Use risk-based queues, rate controls and independent review for consequential decisions, with accessible appeals. Measure precision, recall proxies, resolution time and disparate failure patterns.','Can reporter reputation solve the issue?','It can inform triage but creates cold-start, gaming and feedback-loop risks. Validate it, retain evidence-based review and avoid treating popularity as truth.','How do you measure missed harmful content?','Sample unreported content with appropriate safeguards and expert review, analyze appeals and audits, and state the limits of observable ground truth.'),
f('Leadership','A metric you would retire','Prepare a truthful product interview story.',['Choose a real project where a metric became misleading or incentives distorted behavior.','If you have no direct ownership, use a classroom or volunteer example and state your role accurately.'], 'Explain the metric, failure mechanism, replacement and stakeholder conversation.','A strong answer shows the original purpose, concrete evidence of distortion and your own action. Preserve useful historical comparisons while introducing better outcome and guardrail measures. Do not invent impact; explain what remains unknown.','A leader’s bonus depends on the old metric. What would you do?','Acknowledge the incentive conflict, involve the appropriate decision owner and propose a transition with auditable definitions. Avoid changing rules secretly or blaming individuals.','How would you know the replacement is better?','Test whether it tracks the intended user and business outcome across segments, monitor gaming and compare decisions it changes rather than praising its sophistication.')
],
'data-analytics':[
f('SQL','Customers who came back','Write SQL for a fictional retention report.',['Orders contain customer_id, order_id, paid_at and status.','Define a January cohort by first successful paid order; February retention means at least one successful order in February.'], 'Specify SQL logic, denominators and edge cases.','Compute each customer’s first successful paid timestamp, select January first-timers and left-join distinct February purchasing customers. Divide retained customers by all cohort customers. Define timezone and refund treatment; avoid counting orders as people.','Why can filtering to February first be wrong?','It removes nonreturners and can misidentify first purchase dates. Establish the cohort from full eligible history before checking future activity.','How would you test the query?','Use customers with multiple orders, failed orders before success, a prior-year purchase and no February activity. Assert denominator stability and one row per customer.'),
f('Causal inference','A campaign and a holiday','Evaluate a fictional marketing campaign.',['Sales rose 25% after launch.','The campaign coincided with a holiday and a price reduction; no randomized holdout exists.'], 'Explain what can and cannot be concluded and propose an analysis.','Before-after growth cannot isolate campaign causality. Consider comparable untreated markets or cohorts, pre-trends and concurrent changes; difference-in-differences requires a credible counterfactual. Report uncertainty and limitations rather than assigning all growth to marketing.','Pre-trends differ across regions. What now?','The parallel-trends assumption is doubtful. Seek a better comparison or design a prospective test; statistical adjustment alone cannot guarantee causal identification.','Can regression with many controls fix everything?','No. Unobserved confounding, post-treatment controls and model misspecification remain. Select controls from a causal rationale and state identifying assumptions.'),
f('Metrics','Average order value misleads','Analyze a fictional retail dashboard.',['Period A has 100 orders at $20 each and 100 at $100 each.','Period B has 180 orders at $20 and 20 at $100; segment prices are unchanged.'], 'Calculate average order value and explain the change.','AOV is $60 in A and $28 in B. The change reflects order mix, not lower spend within either segment. Investigate acquisition, demand and margin by segment before recommending pricing changes.','What if the low-price segment has better margin?','Revenue per order may fall while contribution improves. Compare unit contribution and total profit, accounting for fulfillment and acquisition costs.','Which chart would explain this clearly?','Show segment shares alongside within-segment values, with consistent denominators. A decomposition or stacked mix chart is more informative than a lone AOV trend.',[{label:'Period B average order value',answer:28,tolerance:.01,unit:'$'}]),
f('Machine learning','A rare-event classifier','Assess a fictional fraud model.',['Among 10,000 transactions, 100 are fraudulent.','The model flags 80 of those and 495 legitimate transactions.'], 'Calculate precision and recall and explain the operational decision.','Recall is 80/100=80%; precision is 80/575≈13.91%. High recall does not imply a usable alert queue. Compare review capacity, loss avoided, false-positive harm and calibration against a baseline.','Reviewers can inspect only 200 alerts. What changes?','Rank by expected value or calibrated risk, evaluate precision and recall at capacity, and monitor missed fraud. The original threshold is not feasible just because its recall is high.','How would delayed fraud labels affect evaluation?','Use mature cohorts or account explicitly for label delay and verification bias. Avoid treating unconfirmed recent transactions as known legitimate.',[{label:'Precision',answer:13.913,tolerance:.01,unit:'%'},{label:'Recall',answer:80,tolerance:.01,unit:'%'}]),
f('Forecasting','A forecast that knows the sale','Audit a fictional demand model.',['Training uses final weekly promotional spend.','Predictions are made before the week starts, when only planned spend is known.'], 'Define a valid feature pipeline and backtest.','Use information available at prediction time, including planned rather than realized spend. Backtest with rolling time origins, representative horizons and a simple seasonal baseline. Inspect stockouts, promotions and structural changes without leaking future information.','How do stockouts distort demand labels?','Observed sales are censored by availability. Model or flag stockout periods and separate latent demand from realized sales; do not interpret low sales as low demand automatically.','The business cares about underforecasting more. What metric fits?','Use an asymmetric cost or quantile loss aligned to inventory decisions, alongside calibration and service outcomes. State the cost assumptions rather than optimizing generic RMSE alone.'),
f('Data quality','The dashboard changed at midnight','Investigate a fictional revenue metric discrepancy.',['Finance uses UTC month boundaries; operations uses local time.','Both dashboards join orders to line items, and one also joins refunds.'], 'Design reconciliation checks and propose shared definitions.','Reconcile timezone windows, grain, status and refund timing. Check fan-out from many-to-many joins by aggregating each fact table before joining. Produce an exception table and a metric contract with owners and versioning.','Why is DISTINCT not a general fix?','It may hide duplicated rows while discarding legitimate equal-valued transactions. Fix the join grain and keys, then reconcile row counts and sums.','How would you communicate the correction?','Quantify affected periods and decisions, publish the revised definition and restatement, and preserve an audit trail. Do not silently overwrite historical figures.'),
f('Experimentation','A peeking problem','Review a fictional A/B testing habit.',['The team checks a conventional fixed-horizon p-value daily.','It stops the first time p<0.05 and calls the result significant.'], 'Explain the error and design a valid stopping rule.','Repeated optional stopping changes the false-positive rate of a fixed-horizon test. Predefine sample size and analysis timing or use a properly designed sequential method. Include practical effect size, uncertainty and guardrails.','What if the experiment causes severe harm?','Safety stopping is appropriate even before inferential completion. Stop exposure using predefined guardrails, then describe the evidence and limitations honestly.','Can you restart until a test succeeds?','Selecting across repeated trials compounds multiplicity and publication bias. Account for the search process and retain failed results rather than treating the winning run in isolation.'),
f('Communication','The executive wants one number','Present a fictional uncertain business forecast.',['Three plausible demand scenarios imply profits of −$1m, $2m and $5m.','No defensible probabilities have been established.'], 'Create an executive explanation and a decision framework.','Do not average scenarios and label the result expected profit without probabilities. Show drivers, break-even conditions and actions that remain sensible across scenarios. Identify which uncertainty can be reduced before commitment.','The executive insists on a planning number. What do you do?','Choose and label a planning assumption with downside triggers and contingency reserves; distinguish budgeting convention from probabilistic expectation.','What visual helps?','Use a scenario comparison or sensitivity chart with assumptions visible. Avoid a probability distribution graphic that implies unsupported likelihoods.')
],
'data-engineering':[
f('Streaming','A watermark is not a guarantee','Design a fictional event-time aggregation.',['Events may arrive ten minutes late in normal operation.','Daily revenue must be corrected when later events arrive; ingestion is at least once.'], 'Define windows, watermark policy, deduplication and corrections.','Separate event time from processing time. A watermark estimates completeness rather than proving no future arrival. Deduplicate event IDs, define allowed lateness and emit versioned corrections or restatements for late events. Preserve a raw replayable ledger.','An event arrives a day late. What happens?','Route it to a correction or backfill path rather than silently dropping revenue. Reconcile the updated aggregate and notify consumers under a documented finality policy.','Can exactly-once stream processing guarantee correct totals?','Not by itself. Source duplicates, incorrect event IDs, business reversals and sink semantics still matter. Verify end-to-end business invariants.'),
f('Modeling','A customer changes regions','Model a fictional customer dimension.',['Customers can move regions.','Finance needs revenue by region at sale time and by current customer region.'], 'Design dimension history and joins for both questions.','Use effective-dated dimension versions with nonoverlapping intervals and a stable customer key. Join facts to the version valid at sale time for historical reporting; use the current version for current-region views. Name the metrics distinctly.','Two versions overlap. How do you handle it?','Reject or quarantine the conflict and alert the owner; arbitrary first-row selection produces unstable attribution. Validate exactly one valid version per fact timestamp.','A move date is corrected retroactively. What changes?','Restate affected historical joins under a versioned correction process, preserving prior reported values and lineage when required.'),
f('SQL performance','The skewed join','Optimize a fictional large-table join.',['Most keys are small, but one customer owns 40% of rows.','The distributed job spills on one worker while others finish quickly.'], 'Diagnose skew and propose a correct optimization.','Inspect key frequencies and execution partitions. Split heavy keys, use salting with appropriate replication or preaggregate where semantics permit. Do not change join grain to chase speed; verify totals, null handling and duplicate behavior.','The small table fits in memory. What option helps?','A broadcast join may avoid shuffling the large side, subject to memory and engine behavior. It does not remove expensive output cardinality or invalid duplicate keys.','How do you validate the fix?','Compare row counts, key-level aggregates and sampled exact outputs, then measure spill, tail task time and total cost on representative data.'),
f('Reliability','A backfill that overwhelms production','Plan a fictional twelve-month data backfill.',['The source database serves customer requests.','Historical extraction could consume all available read capacity.'], 'Design throttling, checkpoints and validation.','Use bounded batches, a replica or snapshot where appropriate, and explicit resource budgets. Make writes idempotent, checkpoint progress and reconcile partitions. Pause automatically on production latency or replication lag thresholds.','The source changes during extraction. What is needed?','Use a consistent snapshot or combine a snapshot watermark with change capture. Document how updates and deletes during the extraction are reconciled.','A batch fails after writing half its rows. What happens?','Retry with deterministic keys or atomic partition replacement, verify completion markers and avoid marking a checkpoint before durable validated output.'),
f('Governance','Delete means all the copies','Design a fictional deletion workflow.',['Customer data exists in operational storage, analytics tables, caches and backups.','Some records have legitimate retention requirements that must be assessed.'], 'Map ownership, deletion propagation and verification without assuming one universal retention rule.','Inventory data and derived copies, verify the request through an approved process, and coordinate applicable retention requirements with responsible teams. Propagate tombstones or deletion jobs, track exceptions and prevent replay from restoring deleted data.','How do backups fit?','Define controlled retention and restoration procedures that reapply deletions before restored data becomes available. Do not claim immediate physical removal from immutable backups without a supported mechanism.','Can you simply hash the identifier?','Hashing can remain linkable and does not erase other identifying fields. Evaluate reidentification and the actual required outcome rather than equating hashing with deletion.'),
f('Schema evolution','A field changes meaning','Handle a fictional source schema update.',['The field amount previously meant gross amount and now means net of fees.','The type and name are unchanged, so structural validation passes.'], 'Design a semantic data contract and migration.','Version the business definition, add explicit gross/net fields or a schema version, and require producer-consumer review. Backfill only with reconstructible evidence and mark historical comparability limits. Type checks cannot detect a changed meaning.','How would you catch this automatically?','Use distribution, reconciliation and invariant checks against independent totals, plus change notifications. Statistical alerts can detect symptoms but cannot replace semantic ownership.','A consumer cannot migrate immediately. What do you do?','Provide a temporary compatible view only if the old meaning can be reconstructed reliably; otherwise surface the breaking change and coordinate a controlled cutoff.'),
f('Orchestration','A green pipeline with stale data','Investigate a fictional pipeline marked successful.',['Every task exits zero.','The source export contains yesterday’s data, and the dashboard claims to be current.'], 'Define freshness, completeness and correctness checks.','Success should include source watermark, expected partition coverage and reconciliation, not just exit codes. Distinguish no new events from a missing export. Surface last verified data time and block misleading current labels.','What if the business legitimately has zero events?','Use an explicit source completion signal and watermark rather than nonzero row count as the only test. Zero rows can be valid; absent evidence of completeness is different.','How would you assign alert ownership?','Route failures by producer, transport and transformation stage with a runbook and actionable context. Set service objectives around user-visible freshness.'),
f('Cost','Partitioning without pruning','Reduce fictional warehouse costs.',['A 10TB table is partitioned by event_date.','Queries wrap event_date in a function and often scan a year to answer a one-day question.'], 'Propose query, layout and governance improvements.','Inspect execution plans for pruning, rewrite filters to bounded partition predicates and select only needed columns. Consider clustering and aggregates based on workloads, then measure bytes scanned and correctness. Avoid claiming every function prevents pruning across all engines.','Would more partitions always help?','No. Excessive tiny partitions create metadata and scheduling overhead. Choose granularity using volume, access patterns and engine constraints.','How do you prevent cost regression?','Track representative query budgets, plan changes and scan volume; use documented examples and CI checks where practical, without blocking legitimate large analyses.')
],
cybersecurity:[
f('Application security','An object ID is not permission','Review a fictional document API.',['Users request documents by numeric ID.','The endpoint checks that a user is signed in but not that the document belongs to an allowed workspace.'], 'Explain the vulnerability and implement a defensive authorization design.','Enforce object-level authorization using trusted user and workspace context on every request. Random IDs reduce guessing but do not replace permission checks. Test cross-tenant access, revoked membership, shared links and indirect endpoints.','What if the UI hides forbidden IDs?','Clients are not an enforcement boundary. Requests can be constructed directly; the server must authorize the object independently of UI visibility.','How would you investigate past exposure?','Preserve logs, scope potentially unauthorized reads and coordinate incident handling. Distinguish a confirmed weakness from evidence of actual data access.'),
f('Cloud security','A public storage surprise','Respond to a fictional storage configuration issue.',['A bucket containing internal reports is publicly readable.','Access logs are incomplete and a business workflow depends on some public assets.'], 'Contain exposure, preserve evidence and restore only intended access.','Separate intended public assets from private reports, remove inappropriate public permissions and preserve available logs and configuration history. Inventory affected data and credentials, involve incident owners and verify access from an unauthenticated context.','Can you say no one downloaded the reports?','Not with incomplete logs. State the visibility limitation and assess exposure duration and sensitivity; absence of recorded access is not proof of no access.','How would you prevent recurrence?','Use least-privilege templates, policy checks, continuous configuration monitoring and ownership tags; test effective access rather than relying only on a console label.'),
f('Threat modeling','A password reset redesign','Threat-model a fictional password-reset flow.',['The flow sends a reset link to the registered email.','Links currently never expire and can be reused.'], 'Define token properties, validation and abuse controls.','Use high-entropy, scoped, short-lived, single-use tokens stored safely, with server-side consumption and consistent responses that limit account enumeration. Rate-limit abuse and define session revocation after reset. Do not log raw tokens.','Two requests redeem the same link concurrently. What must happen?','Atomically consume the token with the password update so only one succeeds. A read-then-write validity check permits a race.','Should the reset automatically change the registered email?','No. Email change is a separate sensitive flow with verification and notification requirements; a reset token should not silently grant broader privileges.'),
f('Detection','Alerts without useful evidence','Improve a fictional security alert queue.',['Analysts receive 5,000 alerts daily but can investigate 200.','Many alerts repeat the same benign service-account action.'], 'Design triage and evaluate detection quality.','Group correlated events, enrich with asset and identity context, and tune documented benign patterns without blanket suppression. Rank by severity and confidence, sample suppressed events and measure investigation outcomes and missed incidents.','A low-volume alert catches a real incident. Should volume drive priority?','No. Expected harm, context and evidence matter more than frequency alone. Preserve rare high-value detections and assess their precision and coverage.','How do you measure false negatives?','Use controlled detection exercises, retrospective incident review and sampled activity with authorized testing. A quiet queue cannot establish complete coverage.'),
f('Identity','The administrator who left','Audit a fictional offboarding process.',['A departing employee loses their primary login.','They also created service tokens and have access through a partner organization.'], 'Build an access-revocation and ownership-transfer plan.','Inventory direct and federated identities, active sessions, API tokens, groups and shared secrets. Revoke or rotate appropriately, transfer service ownership safely and verify effective denial. Preserve required audit records and avoid breaking critical services blindly.','What if nobody knows which service uses a token?','Use logs and dependency mapping, stage rotation with a controlled overlap if policy permits, and monitor failures. Uncertainty calls for investigation, not indefinite unmanaged access.','How do you prevent shared admin accounts?','Use named privileged identities, just-in-time access and audited service principals with ownership. Establish emergency access procedures rather than sharing a permanent password.'),
f('Vulnerability management','Patch severity versus exposure','Prioritize fictional remediation.',['A critical vulnerability affects an isolated test server with no sensitive data.','A lower-rated issue affects an internet-facing payment service and is actively exploited.'], 'Explain a risk-based prioritization and verification plan.','Combine exploitability, exposure, asset criticality, compensating controls and business impact rather than sorting only by severity score. Rapidly mitigate the exposed service and plan tested remediation for both. Verify deployed versions and effective controls.','The patch breaks a production dependency. What now?','Use a tested compensating control, isolation or rollback while coordinating a safe fix. Assign an owner and expiry to the exception; do not quietly accept indefinite risk.','What evidence closes the ticket?','Confirm the affected paths and versions are remediated in production, validate behavior and monitor recurrence. A successful deployment command alone is insufficient.'),
f('Secure development','A secret in a repository','Respond to a fictional exposed API credential.',['A credential was committed to a public repository yesterday.','The commit has since been deleted from the latest branch.'], 'Give immediate and preventive actions.','Revoke or rotate the credential, assess its privileges and review use during exposure. Removing a commit does not invalidate copies, forks or history. Replace hardcoded credentials with an appropriate secret-management flow and add scanning.','No suspicious usage appears in logs. Can the key stay active?','No. Treat the exposed credential as compromised because copies may be used later and logging may be incomplete. Rotation addresses the ongoing risk.','How do you rotate without outage?','Use the provider’s supported overlap or staged update process, deploy the replacement securely, verify service health and revoke the old key promptly.'),
f('Incident communication','The first executive update','Write a fictional incident update.',['A production service is unavailable and suspicious activity is under investigation.','Data loss is unconfirmed; restoration timing is uncertain.'], 'Draft a concise update separating facts, unknowns, actions and next checkpoint.','State confirmed impact and time, what is being investigated, containment and recovery ownership, and when the next update will arrive. Avoid attributing an attacker or claiming a breach without evidence. Give decision makers actionable needs, not speculative certainty.','Leadership demands a restoration time. What do you say?','Provide a conditional range only if supported by recovery evidence, name dependencies and commit to a next assessment time. Do not invent a deadline to reduce pressure.','When should customers be notified?','Coordinate incident, legal and communications owners based on actual impact and applicable obligations. Provide accurate service information promptly without guessing universal notification rules.')
],
'corporate-finance':[
f('Capital budgeting','The attractive payback shortcut','Compare a fictional investment with doing nothing.',['Upfront cost is $100,000.','It generates $30,000 at each year-end for four years; discount rate 10%; no terminal value.'], 'Calculate NPV and explain the decision beyond simple payback.','PV of four payments is about $95,096, so NPV is about −$4,904. Simple payback is 3.33 years but ignores time value. Validate cash-flow assumptions and consider constraints and nonfinancial requirements separately.','The useful life extends to five years. What changes?','An extra $30,000 at year five adds about $18,628 in PV, making NPV about $13,724. Verify that operating and maintenance assumptions still hold.','Two projects have different scales. Is IRR enough?','No. Compare incremental NPV under capital constraints and timing, considering mutually exclusive choices. A higher percentage return can create less absolute value.'),
f('Variance analysis','Revenue beats budget for the wrong reason','Analyze a fictional monthly result.',['Budget: 1,000 units at $100. Actual: 1,200 units at $90.','Use budget price for volume variance and actual volume for price variance.'], 'Bridge revenue variance and explain what else matters.','Budget revenue is $100,000 and actual $108,000. Volume contributes +$20,000; price contributes −$12,000, net +$8,000. Evaluate margin, mix, returns and acquisition cost before calling the result a win.','What if actual variable cost is much higher?','Build a contribution bridge; revenue growth may hide profit erosion. Separate rate, efficiency and mix effects with clearly stated conventions.','Why might another analyst get different intermediate variances?','Alternative decomposition conventions allocate interaction effects differently. Reconcile to the same total and state the chosen method rather than treating each intermediate value as uniquely correct.',[{label:'Net revenue variance',answer:8000,tolerance:1,unit:'$'}]),
f('Working capital','The cash conversion cycle','Review fictional operating cash efficiency.',['Days inventory outstanding are 60; days sales outstanding 45; days payable outstanding 30.','Daily cost of goods sold is $20,000; assume stable volume.'], 'Compute the cash conversion cycle and cash released by reducing inventory days to 50.','The cycle is 60+45−30=75 days. Ten fewer inventory days release approximately $200,000 at the stated cost basis. This is a one-time release, not recurring annual profit; examine service and supplier effects.','Payables are stretched by another 20 days. Is that free financing?','It may release cash but can harm suppliers, discounts and continuity or breach terms. Assess negotiated terms and sustainability rather than treating late payment as a costless lever.','Why use cost of goods sold for inventory?','Inventory is generally held at cost, while receivables relate to sales. Mixing revenue and cost denominators can materially distort the cash estimate.',[{label:'Cash conversion cycle',answer:75,tolerance:0,unit:'days'},{label:'Approximate inventory cash release',answer:200000,tolerance:1,unit:'$'}]),
f('Forecasting','A headcount plan with hidden timing','Forecast fictional personnel costs.',['Ten hires have annual salary $120,000 each and start July 1.','Benefits are 25% of salary; recruiting cost is $8,000 per hire paid on start.'], 'Estimate first-year cost and next-year run rate, ignoring raises and attrition.','Half-year salary is $600,000, benefits $150,000 and recruiting $80,000, totaling $830,000. Next-year salary and benefits run rate is $1.5m without repeat recruiting. Separate expense timing from cash timing.','Half the hires slip to October 1. What changes?','Salary becomes $450,000, benefits $112,500 and recruiting remains $80,000 if all start that year, totaling $642,500. Delivery capacity also changes; savings alone are not success.','What if some hires replace contractors?','Include avoided contractor spend with realistic overlap and notice periods. Do not count both the full contractor savings and immediate productivity without evidence.',[{label:'First-year total hiring cost',answer:830000,tolerance:1,unit:'$'}]),
f('Unit economics','Growth with negative contribution','Evaluate a fictional delivery service.',['Each order produces $25 revenue.','Variable fulfillment costs $18, payment costs $1 and expected refunds $2; customer acquisition is tracked separately.'], 'Calculate contribution and identify what is needed for an expansion decision.','Contribution before acquisition is $4 per order. Include repeat behavior, acquisition cost, fixed capacity steps and cash timing before expanding. A positive unit contribution does not establish overall profitability.','A promotion reduces price by $5. What happens?','Contribution becomes −$1 before acquisition unless costs or customer behavior change. Model credible future value and cap the experiment rather than assuming volume repairs negative economics.','How should refunds be modeled?','Use expected refunds for comparable cohorts and avoid double-counting refunded revenue and refund expense. Reconcile the accounting convention and inspect tail risk.',[{label:'Contribution per order before acquisition',answer:4,tolerance:.01,unit:'$'}]),
f('Treasury','A currency budget surprise','Assess fictional foreign-currency exposure.',['A business expects to receive €2m in three months and pays costs in Canadian dollars.','Budget rate is CAD1.50/€; downside scenario is CAD1.40/€; ignore hedging costs initially.'], 'Quantify the revenue sensitivity and frame a hedging decision.','Budget receipts are CAD3m versus CAD2.8m in the downside, a CAD200k reduction. Match hedging to committed versus forecast exposure, timing and policy; do not speculate on exchange direction.','The customer may cancel half the order. What changes?','A full fixed hedge could overhedge uncertain exposure. Consider staged hedging or suitable optionality within policy, explicitly evaluating costs and forecast confidence.','Does a hedge eliminate business risk?','No. Counterparty, timing, basis and forecast risks remain, and operating competitiveness can change. Explain what the instrument covers and what it does not.',[{label:'Downside reduction in CAD receipts',answer:200000,tolerance:1,unit:'CAD'}]),
f('Business partnering','A budget cut that moves cost','A fictional department proposes outsourcing support.',['Internal cost is $1m annually.','Vendor quote is $700,000, but internal contract oversight and escalation work remain.'], 'Build a total-cost comparison and decision process.','Separate avoidable costs from allocated costs, add retained work, transition, contract changes and quality effects. Validate service levels and exit costs. A lower vendor invoice is not proof of equivalent savings.','Only $500,000 of internal cost is avoidable. What does that imply?','The quoted vendor alone exceeds avoidable savings by $200,000 before retained and transition costs. Strategic benefits would need independent justification.','How do you handle a leader committed to outsourcing?','Present the reconciled bridge and assumptions, offer a scoped pilot or alternatives and document the decision. Challenge the economics respectfully rather than manipulating the baseline.'),
f('Controls','A forecast override without evidence','Respond to a fictional reporting request.',['A manager asks you to move an expected cost into next quarter to meet the forecast.','The service was already delivered this quarter and no supporting adjustment exists.'], 'Explain your response and the distinction between forecasting and accounting.','Verify the facts, follow the applicable accounting and approval process and record the cost in the appropriate period. Forecast targets do not change economic timing. Explain the variance transparently and escalate unresolved pressure through established channels.','What if the invoice has not arrived?','Absence of an invoice does not by itself move an incurred cost. Assess accrual evidence and estimation under the relevant policy, then true up when supported.','How do you preserve the working relationship?','Focus on facts and a compliant path, such as explaining the variance and revising the outlook. Be clear about boundaries and avoid personal accusations.')
],
 'technical-sales':[
f('Discovery','The requested demo is not the problem','Plan a fictional first discovery call.',['A prospect asks for a dashboard demo.','Their stated problem is that regional managers disagree about inventory and decisions take days.'], 'Write discovery questions and a tailored demonstration plan.','Understand the workflow, data sources, disagreement, decision owner and cost of delay before choosing features. Demonstrate a relevant end-to-end task with explicit success criteria. A visually impressive dashboard does not resolve inconsistent definitions or inaccessible data.','The buyer refuses discovery and wants a demo now. What do you do?','Offer a short hypothesis-led demo, state assumptions and ask targeted questions around each workflow. Avoid pretending the fit is established.','How do you quantify value without private numbers?','Use a transparent illustrative model and ask the buyer to validate ranges later. Keep assumptions distinct from verified savings and avoid inventing customer data.'),
f('Architecture','A residency requirement','Respond to a fictional enterprise requirement.',['The prospect requires specified data to remain in a particular region.','Your standard diagram omits backups, logs and support access.'], 'Map the data flow and define what must be verified before making a commitment.','Inventory primary storage, replicas, backups, telemetry, subprocessors and support access. Verify supported configurations and contractual scope with security and legal owners. Residency, sovereignty and access control are related but not interchangeable.','The main database is in-region. Is that sufficient?','Not if logs, backups or other covered data leave the region. Trace the complete lifecycle and distinguish the specific buyer requirement from a broad marketing claim.','The product cannot satisfy one mandatory constraint. What next?','State the gap, explore verified alternatives or a no-fit decision, and avoid promising an uncommitted roadmap. Trust is more valuable than an unsupported compliance assertion.'),
f('Value engineering','The ROI denominator','Audit a fictional proposal.',['Annual benefit is estimated at $200,000.','Annual subscription is $80,000 and implementation costs $40,000 once; ignore discounting for the first-year view.'], 'Calculate first-year net benefit and ROI on first-year cost, then qualify the estimate.','First-year cost is $120,000, net benefit $80,000 and ROI $80,000/$120,000≈66.67%. Validate benefit realization, adoption and omitted internal labor. State the horizon and denominator; do not call gross benefit divided by cost net ROI.','Only half the benefit is realized in year one. What changes?','Benefit is $100,000, net benefit −$20,000 and ROI −16.67%. Ramp timing matters, and later-year benefits should be modeled separately.','How would you prove savings after deployment?','Agree a baseline and owner, distinguish cash savings from released capacity, and compare measured outcomes with the promised assumptions.',[{label:'First-year ROI on cost',answer:66.6667,tolerance:.01,unit:'%'}]),
f('Commercial judgment','The free pilot that never ends','Scope a fictional proof of value.',['The buyer requests three integrations and six months of free use.','There is no budget owner, success metric or purchase decision date.'], 'Propose a bounded next step and qualify the opportunity.','Agree a narrow hypothesis, representative data, responsible stakeholders, acceptance criteria and a decision date. Confirm technical and commercial feasibility before committing large engineering effort. A paid discovery phase or smaller pilot may be appropriate.','A competitor offers the full pilot free. How do you respond?','Explain scope, support and decision value without unsupported competitor criticism. Assess strategic value and opportunity cost; do not match concessions automatically.','The pilot succeeds but procurement has no budget. What was missing?','Commercial qualification and decision ownership. Reconfirm the buying process, funding timing and next viable step instead of retroactively labeling technical success a committed sale.'),
f('Negotiation','A discount for nothing','Evaluate a fictional last-minute pricing demand.',['The buyer requests 25% off in exchange for signing this week.','Legal review is incomplete and the proposed volume is not committed.'], 'Create a principled negotiation plan.','Clarify the buyer’s constraint and verified decision process. Any concession should be approved and exchanged for measurable value such as committed volume or terms, with realistic scope. A verbal deadline is not evidence of executable signature readiness.','What if the discount is required to retain a strategic account?','Assess contribution, alternatives, precedent and long-term value, and seek appropriate approval. A strategic rationale should be documented rather than assumed.','How do you avoid a bad contract?','Keep legal, security and delivery obligations visible; do not trade away unsupported service commitments merely to preserve headline price.'),
f('Customer success','Usage rises but value does not','Review a fictional expansion opportunity.',['Active users doubled after mandatory training.','The customer’s target outcome—faster month-end reporting—has not improved.'], 'Diagnose adoption quality and recommend an account plan.','Separate activity from completed business outcomes. Map workflow bottlenecks, data quality and approval delays, then agree measurable improvements and owners. Expansion should follow demonstrated fit rather than activity alone.','The champion asks for more licenses. What do you verify?','Check who needs access, what work will improve and whether existing barriers persist. More seats may help, but do not present them as the cure for an unaddressed process problem.','How would you report progress?','Track time to complete the target workflow, error rates and user effort alongside adoption. Explain confounders and compare consistent periods.'),
f('Technical communication','Explain an outage to the buyer','Handle a fictional customer call during service degradation.',['The engineering team has confirmed elevated errors but not the root cause.','The buyer asks whether all their data is safe and when service will recover.'], 'Draft an honest update and an escalation plan.','Share confirmed impact, available workarounds, incident ownership and next update time. Do not guarantee data integrity or recovery timing beyond evidence. Coordinate with incident communications and record customer-specific needs.','The customer threatens to cancel unless you guarantee recovery. What do you say?','Acknowledge the impact and provide concrete escalation and contingency actions. Do not invent a guarantee; explain what is verified and when the next decision can be made.','After recovery, what should the follow-up contain?','Provide a supported timeline, impact, corrective actions and owners, with unresolved questions identified. Distinguish restored service from completed root-cause analysis.'),
f('Ethics','A reference customer without consent','Respond to a fictional sales request.',['A teammate wants to share another customer’s private architecture diagram.','The prospect says it would settle their security concern.'], 'Offer a useful response that respects confidentiality.','Do not share private customer material without proper authorization. Use approved anonymized examples, public references or a security review under appropriate agreements. Explain capabilities with evidence without exposing another customer’s systems.','Can you simply remove the customer name?','Not necessarily; architecture details and context may identify the customer or reveal sensitive information. Use an approved sanitized artifact, not ad hoc redaction as assumed permission.','What if the material has already been sent?','Notify the responsible internal team promptly, preserve the facts and follow incident and customer-communication procedures. Do not quietly delete evidence or pretend no disclosure occurred.')
]
};
export function expandedCareerCases(roleId:string):Array<Seed&{topic:string;numbers:NumberCheck[];drillKind:'Core'|'Deep dive'|'Pressure test'}>{
 return (careerFamilies[roleId]||[]).flatMap(s=>[
 {...s,numbers:s.numbers||[],drillKind:'Core' as const},
 ...s.followups.map((question,i)=>({...s,title:`${i===0?'Deep dive':'Pressure test'}: ${s.title}`,prompt:`${s.prompt}\nInterviewer ${i===0?'follow-up':'challenge'}: ${question}`,task:`Answer the changed situation directly: ${question} Show the reasoning and explain which assumptions from the core case still hold.`,benchmark:s.probeAnswers[i],numbers:[],drillKind:(i===0?'Deep dive':'Pressure test') as 'Deep dive'|'Pressure test'}))
 ]);
}
